using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;

namespace WebApiDesignDemo;

// === 请求/响应模型 ===

public record CreateProductRequest(
    [Required(ErrorMessage = "产品名称不能为空")]
    [StringLength(100, MinimumLength = 2, ErrorMessage = "名称长度 2-100 字符")]
    string Name,

    [StringLength(500)] string? Description,

    [Required]
    [Range(0.01, 100000)] decimal Price,

    [Required]
    [Range(0, 10000)] int Stock,

    [Required]
    [StringLength(50)] string Category
);

// PATCH 用可空字段区分「没传」和「传 null」
public record PatchProductRequest(
    string? Name,
    string? Description,
    decimal? Price,
    int? Stock
);

public record ProductResponse(
    int Id, string Name, string? Description,
    decimal Price, int Stock, string Category,
    DateTime CreatedAt, DateTime? UpdatedAt
);

public record PagedResult<T>(
    IReadOnlyList<T> Items, int Total,
    int Page, int PageSize, bool HasNext
);

// === 控制器 ===

[ApiController]
[Route("api/[controller]")]
[Produces("application/json")]
public class ProductsController : ControllerBase
{
    private static readonly Dictionary<int, ProductResponse> Products = new();
    private static int _nextId = 1;

    // GET /api/products?category=books&minPrice=10&page=1&pageSize=20
    [HttpGet]
    [ProducesResponseType(typeof(PagedResult<ProductResponse>), 200)]
    public IActionResult GetAll(
        [FromQuery] string? category,
        [FromQuery] decimal? minPrice,
        [FromQuery] decimal? maxPrice,
        [FromQuery] string? search,
        [FromQuery] string sortBy = "name",
        [FromQuery] bool desc = false,
        [FromQuery] int page = 1,
        [FromQuery] int pageSize = 20)
    {
        var query = Products.Values.AsEnumerable();

        if (!string.IsNullOrEmpty(category))
            query = query.Where(p => p.Category == category);
        if (minPrice.HasValue) query = query.Where(p => p.Price >= minPrice);
        if (maxPrice.HasValue) query = query.Where(p => p.Price <= maxPrice);
        if (!string.IsNullOrEmpty(search))
            query = query.Where(p => p.Name.Contains(search));

        // 排序白名单，防止任意字段排序
        query = (sortBy.ToLower(), desc) switch
        {
            ("price", true) => query.OrderByDescending(p => p.Price),
            ("price", false) => query.OrderBy(p => p.Price),
            ("name", true) => query.OrderByDescending(p => p.Name),
            _ => query.OrderBy(p => p.Name)
        };

        var total = query.Count();
        var items = query.Skip((page - 1) * pageSize).Take(pageSize).ToList();

        return Ok(new PagedResult<ProductResponse>(
            items, total, page, pageSize,
            HasNext: page * pageSize < total));
    }

    // GET /api/products/5
    [HttpGet("{id:int:min(1)}")]
    [ProducesResponseType(typeof(ProductResponse), 200)]
    [ProducesResponseType(typeof(ProblemDetails), 404)]
    public IActionResult GetById([FromRoute] int id)
    {
        if (!Products.TryGetValue(id, out var product))
            return NotFound(new ProblemDetails
            {
                Status = 404,
                Title = "资源不存在",
                Detail = $"产品 {id} 不存在"
            });

        // 设置 ETag 供条件请求
        Response.Headers.ETag = $"\"{product.Id}-{product.UpdatedAt?.Ticks ?? product.CreatedAt.Ticks}\"";
        return Ok(product);
    }

    // POST /api/products  →  201 Created + Location
    [HttpPost]
    [ProducesResponseType(typeof(ProductResponse), 201)]
    [ProducesResponseType(typeof(ProblemDetails), 400)]
    public IActionResult Create([FromBody] CreateProductRequest request)
    {
        // [ApiController] 自动验证，无需手动检查 ModelState
        var product = new ProductResponse(
            _nextId++, request.Name, request.Description,
            request.Price, request.Stock, request.Category,
            DateTime.UtcNow, null);

        Products[product.Id] = product;

        // 201 + Location 头，客户端可 GET 新资源
        return CreatedAtAction(
            nameof(GetById),
            new { id = product.Id },
            product);
    }

    // PUT /api/products/5  →  全量替换，幂等
    [HttpPut("{id:int:min(1)}")]
    [ProducesResponseType(typeof(ProductResponse), 200)]
    [ProducesResponseType(typeof(ProblemDetails), 404)]
    public IActionResult Update([FromRoute] int id, [FromBody] CreateProductRequest request)
    {
        if (!Products.TryGetValue(id, out var existing))
            return NotFound(new ProblemDetails
            {
                Status = 404,
                Title = "资源不存在",
                Detail = $"产品 {id} 不存在"
            });

        // PUT 是全量替换，所有字段都用新值覆盖
        var updated = existing with
        {
            Name = request.Name,
            Description = request.Description,
            Price = request.Price,
            Stock = request.Stock,
            Category = request.Category,
            UpdatedAt = DateTime.UtcNow
        };

        Products[id] = updated;
        return Ok(updated);
    }

    // PATCH /api/products/5  →  部分更新
    [HttpPatch("{id:int:min(1)}")]
    [ProducesResponseType(typeof(ProductResponse), 200)]
    [ProducesResponseType(typeof(ProblemDetails), 404)]
    public IActionResult Patch([FromRoute] int id, [FromBody] PatchProductRequest request)
    {
        if (!Products.TryGetValue(id, out var existing))
            return NotFound(new ProblemDetails
            {
                Status = 404,
                Title = "资源不存在",
                Detail = $"产品 {id} 不存在"
            });

        // PATCH 只更新传来的字段，未传的保持原值
        var updated = existing with
        {
            Name = request.Name ?? existing.Name,
            Description = request.Description ?? existing.Description,
            Price = request.Price ?? existing.Price,
            Stock = request.Stock ?? existing.Stock,
            UpdatedAt = DateTime.UtcNow
        };

        Products[id] = updated;
        return Ok(updated);
    }

    // DELETE /api/products/5  →  204 No Content，幂等
    [HttpDelete("{id:int:min(1)}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 404)]
    public IActionResult Delete([FromRoute] int id)
    {
        if (!Products.Remove(id))
            return NotFound(new ProblemDetails
            {
                Status = 404,
                Title = "资源不存在",
                Detail = $"产品 {id} 不存在"
            });

        return NoContent();
    }
}

